"""Core immutable map and mutable fleet entities."""

from __future__ import annotations

from dataclasses import dataclass, field

Position = tuple[int, int]


@dataclass(frozen=True, slots=True)
class GridMap:
    width: int
    height: int
    obstacles: frozenset[Position] = frozenset()

    def __post_init__(self) -> None:
        if self.width <= 0 or self.height <= 0:
            raise ValueError("map dimensions must be positive")
        if any(not self.contains(cell) for cell in self.obstacles):
            raise ValueError("obstacle lies outside the map")

    def contains(self, position: Position) -> bool:
        x, y = position
        return 0 <= x < self.width and 0 <= y < self.height

    def traversable(self, position: Position) -> bool:
        return self.contains(position) and position not in self.obstacles

    def neighbors(self, position: Position) -> tuple[Position, ...]:
        x, y = position
        candidates = ((x, y - 1), (x - 1, y), (x + 1, y), (x, y + 1))
        return tuple(candidate for candidate in candidates if self.traversable(candidate))


@dataclass(slots=True)
class Task:
    task_id: str
    pickup: Position
    dropoff: Position
    assigned_robot: str | None = None
    picked_up: bool = False
    completed: bool = False


@dataclass(slots=True)
class Robot:
    robot_id: str
    position: Position
    route: list[Position] = field(default_factory=list)
    task_id: str | None = None
    distance_travelled: int = 0

    @property
    def idle(self) -> bool:
        return self.task_id is None

"""Command-line demonstration for the local simulator."""

from __future__ import annotations

import argparse
import json
import sys

from .model import GridMap, Robot, Task
from .simulator import FleetSimulator


def _all_tasks_done(simulator: FleetSimulator) -> bool:
    metrics = simulator.metrics()
    return metrics["tasks_completed"] == metrics["tasks_total"]


def demo(steps: int, checkpoint: str | None = None) -> dict[str, object]:
    grid = GridMap(8, 6, frozenset({(3, 1), (3, 2), (3, 3), (5, 4)}))
    robots = [Robot("R-01", (0, 0)), Robot("R-02", (7, 5))]
    tasks = [Task("T-100", (1, 4), (6, 0)), Task("T-200", (6, 5), (0, 2))]
    simulator = FleetSimulator(grid, robots, tasks)
    for _ in range(steps):
        simulator.step()
        if _all_tasks_done(simulator):
            break
    if checkpoint is not None:
        simulator.save_checkpoint(checkpoint)
    return simulator.snapshot()


def resume(source: str, steps: int, checkpoint: str | None = None) -> dict[str, object]:
    simulator = FleetSimulator.load_checkpoint(source)
    for _ in range(steps):
        # Already-complete runs (including an empty task list) report state
        # without advancing another tick.
        if _all_tasks_done(simulator):
            break
        simulator.step()
        if _all_tasks_done(simulator):
            break
    if checkpoint is not None:
        simulator.save_checkpoint(checkpoint)
    return simulator.snapshot()


def main(argv: list[str] | None = None) -> None:
    parser = argparse.ArgumentParser(prog="warehouse-fleet")
    subparsers = parser.add_subparsers(dest="command", required=True)

    demo_parser = subparsers.add_parser("demo", help="run the deterministic sample scenario")
    demo_parser.add_argument("--steps", type=int, default=12)
    demo_parser.add_argument(
        "--checkpoint",
        metavar="FILE",
        help="save simulator state to FILE after the run",
    )

    resume_parser = subparsers.add_parser("resume", help="continue a simulator from a checkpoint")
    resume_parser.add_argument("file", help="checkpoint file to resume from")
    resume_parser.add_argument("--steps", type=int, required=True, help="maximum ticks to run")
    resume_parser.add_argument(
        "--checkpoint",
        metavar="FILE",
        help="save updated state to FILE; defaults to leaving the source untouched",
    )

    args = parser.parse_args(argv)
    if args.steps < 0:
        parser.error("--steps must be non-negative")

    try:
        if args.command == "demo":
            snapshot = demo(args.steps, args.checkpoint)
        else:
            snapshot = resume(args.file, args.steps, args.checkpoint)
    except (ValueError, OSError) as exc:
        print(f"{args.command}: {exc}", file=sys.stderr)
        raise SystemExit(1) from exc

    print(json.dumps(snapshot, ensure_ascii=False, sort_keys=True, indent=2))


if __name__ == "__main__":
    main()

"""Deterministic shortest-path search for four-way warehouse grids."""

from __future__ import annotations

from collections import deque

from .model import GridMap, Position


def shortest_path(grid: GridMap, start: Position, goal: Position) -> list[Position]:
    """Return positions after *start* through *goal*, or raise when unreachable."""
    if not grid.traversable(start) or not grid.traversable(goal):
        raise ValueError("path endpoint is not traversable")
    if start == goal:
        return []
    queue = deque([start])
    previous: dict[Position, Position | None] = {start: None}
    while queue:
        current = queue.popleft()
        for neighbor in grid.neighbors(current):
            if neighbor in previous:
                continue
            previous[neighbor] = current
            if neighbor == goal:
                queue.clear()
                break
            queue.append(neighbor)
    if goal not in previous:
        raise ValueError(f"no route from {start} to {goal}")
    path: list[Position] = []
    cursor = goal
    while cursor != start:
        path.append(cursor)
        parent = previous[cursor]
        if parent is None:
            raise RuntimeError("broken predecessor chain")
        cursor = parent
    path.reverse()
    return path

